business_rule.script:

(function executeRule(current, previous) {
  // Auto-assign the case to the current user if assigned_to is empty
  if (!current.assigned_to || current.assigned_to.toString() === '') {
    current.assigned_to = gs.getUserID();
    gs.info('Case ' + current.case_number + ' automatically assigned to ' + gs.getUserName());
  }
})(current, previous);
